{
  "__type": {
    "fields": [
      {
        "name": "stats",
        "description": "Network stats: block height, TPS, avg block time, proof/operator counts, totals."
      },
      {
        "name": "blocks",
        "description": "Recent blocks (newest first)."
      },
      {
        "name": "block",
        "description": "A block by hash or number."
      },
      {
        "name": "transactions",
        "description": "Recent transactions (extrinsics)."
      },
      {
        "name": "transaction",
        "description": null
      },
      {
        "name": "htlcs",
        "description": "HTLC contracts, optionally filtered by status or address (sender or recipient)."
      },
      {
        "name": "htlc",
        "description": null
      },
      {
        "name": "pouiProofs",
        "description": "Proof-of-Useful-Inference proofs (newest first)."
      },
      {
        "name": "pouiLeaderboard",
        "description": "Top PoUI miners by accumulated G_n weight; 'since' is a unix-ms cutoff."
      },
      {
        "name": "account",
        "description": "An account by SS58 address."
      },
      {
        "name": "inferenceSpend",
        "description": "Indexed best-head inference paid in exact planck by the original channel payer. Bounds select terminal-recognized cumulative payments, including prior forward availability payments; without bounds, the legacy lifecycle summary is returned. Legacy payment projections require a fresh reindex."
      },
      {
        "name": "inferenceReceived",
        "description": "Indexed best-head miner receipts in exact planck, recognized at the terminal timestamp with inclusive Unix-ms bounds. Forward totals include earlier availability payments once. Legacy payment projections require a fresh reindex."
      },
      {
        "name": "htlcPaid",
        "description": "Indexed best-head HTLC escrow paid by authoritative payer in exact planck, with inclusive Unix-ms bounds. Legacy account projections are unavailable until a fresh reindex."
      },
      {
        "name": "htlcReceived",
        "description": "Indexed best-head HTLC escrow received by decoded recipient in exact planck, with inclusive Unix-ms bounds. Legacy account projections are unavailable until a fresh reindex."
      },
      {
        "name": "sponsorPositions",
        "description": "Sponsor-owned slashable positions backing miners/validators."
      },
      {
        "name": "computeChannels",
        "description": "Compute-channel lifecycle rows with payment/evidence state and linked settlement provenance."
      },
      {
        "name": "computeChannel",
        "description": "A compute channel by its on-chain channel id."
      },
      {
        "name": "settlementPrices",
        "description": "Realized settlement tape, filterable by model hash, GPU SKU, participants, or assurance tier."
      },
      {
        "name": "settlementPrice",
        "description": "One realized settlement by channel id."
      },
      {
        "name": "reliabilityEvents",
        "description": "Raw availability/outage evidence, separate from settlement prices and FRCR."
      },
      {
        "name": "minerGhostStatsSnapshots",
        "description": "Historical on-chain MinerGhostStats snapshots pinned to each ghost event block."
      },
      {
        "name": "minerReliability",
        "description": "Cumulative raw reliability facts for one miner."
      },
      {
        "name": "minerReliabilitySeries",
        "description": "Day/epoch availability series; never an FRCR input."
      },
      {
        "name": "networkValue",
        "description": "Realized effective value: D₂ (coalitions) + n_eff (agents, over model_hash) + concentration over PoUI value-shares; 'since' = unix-ms cutoff."
      },
      {
        "name": "termCurve",
        "description": "Transaction-anchored FCU forward curve; funded quotes are returned only in the separate indicative field."
      }
    ]
  }
}
